<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserWebauthnCredential\Domain\ValueObject\Accessor\UserWebauthnCredentialAaguidAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserWebauthnCredentialAaguidAccessor trait.
 *
 * Covers null default, string/VO assignment via withAaguid,
 * getAaguid/aaguid accessors, and isAaguidChanged with/without original.
 */
class UserWebauthnCredentialAaguidAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withAaguid creates a new instance with the Aaguid set
     * from a string value, and getAaguid returns the primitive string.
     */
    public function testWithAaguidFromString(): void
    {
        // Arrange
        $holder = new ImplWithUserWebauthnCredentialAaguidAccessorUnitTest();

        // Act
        $result = $holder->withAaguid('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getAaguid());
    }
    /**
     * Asserts that withaaguid has access to the value object
     * from a string value, and getAaguid returns the primitive string.
     */
    public function testWithAaguidFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithUserWebauthnCredentialAaguidAccessorUnitTest();

        // Act
        $result = $holder->withAaguid('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->aaguid()->value());
    }
    public function testChangedAaguid(): void
    {
        // Arrange
        $holder = new ImplWithUserWebauthnCredentialAaguidAccessorUnitTest();
        $original = $holder->withAaguid('one');
        $same = $holder->withAaguid('one');
        $modified = $holder->withAaguid('other');

        // Act
        $unchanged = $holder->isAaguidChanged();
        $withSame = $original->isAaguidChanged($same);
        $withDiferent = $original->isAaguidChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithUserWebauthnCredentialAaguidAccessorUnitTest
{
    use UserWebauthnCredentialAaguidAccessor;
}
